package com.smarthub.plus;
import android.content.*;
import java.util.*;
import java.util.regex.*;
/** Reception measurements are separate quantities and expire with their observed channel. */
final class ReceptionData {
 static final Set<String> BER_IDS=new HashSet<>(Arrays.asList("ber","channel_ber","tv_ber","tv_channel_ber","tv_channel_info_ber","satellite_detail_info_tv_ber_value"));
 static final Set<String> SAT_IDS=new HashSet<>(Arrays.asList("channel_info_satellite_name_tv","tv_channel_info_satellite_name","tv_satellite_name","satellite_detail_info_tv_satellite_value","tv_sat_name"));
 static final Set<String> BITRATE_IDS=new HashSet<>(Arrays.asList("channel_bitrate","tv_bitrate"));
 static boolean accepts(String id){return IDS.contains(id)||BER_IDS.contains(id)||SAT_IDS.contains(id)||BITRATE_IDS.contains(id);}
 static boolean belongsTo(SatelliteState state,Map<String,String> fields){try{return state.channelId.equals("Aurum:"+Integer.parseInt(fields.getOrDefault("selected_channel_index","")))&&ChannelCatalogue.normalized(state.channelName).equals(ChannelCatalogue.normalized(fields.getOrDefault("selected_channel","")));}catch(Exception invalid){return false;}}
 static final Set<String> IDS=new HashSet<>(Arrays.asList("tv_strength_percent","tv_quality_percent","tv_channel_info_snr","tv_channel_snr","satellite_detail_info_tv_snr_value","tv_snr","channel_snr","snr"));
 static String number(String input,boolean percent){if(input==null)return "";StringBuilder a=new StringBuilder();for(char ch:input.toCharArray()){int digit=Character.digit(ch,10);a.append(digit>=0?(char)('0'+digit):ch=='٫'?'.':ch=='٪'?'%':ch);}Matcher m=Pattern.compile("(?<![0-9])([0-9]{1,5}(?:[.,][0-9]{1,2})?)\\s*(%|[dD][bB])?").matcher(a);if(!m.find())return "";double value;try{value=Double.parseDouble(m.group(1).replace(',','.'));}catch(Exception e){return "";}if(percent&&(value<0||value>100)||value>65535)return "";return m.group(1).replace(',','.')+(percent?"%":m.group(2)==null?"":m.group(2));}
 static void observe(Context c,SatelliteState channel,Map<String,String> fields){String s=number(fields.get("tv_strength_percent"),true),q=number(fields.get("tv_quality_percent"),true),snr="";for(String id:IDS)if(!id.contains("percent")){snr=number(fields.get(id),false);if(!snr.isEmpty())break;}String ber=first(fields,BER_IDS),sat=first(fields,SAT_IDS),rate=first(fields,BITRATE_IDS);if(s.isEmpty()&&q.isEmpty()&&snr.isEmpty()&&ber.isEmpty()&&sat.isEmpty()&&rate.isEmpty()||channel.channelId.isEmpty())return;c.getSharedPreferences("smarthub",0).edit().putString("reception_channel",channel.channelId).putString("reception_name",channel.channelName).putString("reception_strength",s).putString("reception_quality",q).putString("reception_snr",snr).putString("reception_ber",ber(ber)).putString("reception_satellite",sat).putString("reception_bitrate",bitrate(rate)).putLong("reception_observed_at",System.currentTimeMillis()).apply();}
 static String first(Map<String,String> values,Set<String> ids){for(String id:ids){String value=values.getOrDefault(id,"").trim();if(!value.isEmpty())return value;}return "";}
 static String ber(String value){if(value==null)return "";Matcher m=Pattern.compile("(?i)(?<![0-9])([0-9]+(?:[.,][0-9]+)?(?:e[+-]?[0-9]+)?)").matcher(value);return m.find()?m.group(1):"";}
 static String bitrate(String value){if(value==null)return "";Matcher m=Pattern.compile("(?i)[0-9]+(?:[.,][0-9]+)? ?[kmg]?(?:bps|bit/s|b/s)").matcher(value);return m.find()?m.group():"";}
 static String value(Context c,SatelliteState s,String field){if(field.equals("strength")||field.equals("quality")||field.equals("snr")||field.equals("ber"))return DirectReceiverSignal.value(s,field);SharedPreferences p=c.getSharedPreferences("smarthub",0);return s.channelId.equals(p.getString("reception_channel",""))&&s.channelName.equals(p.getString("reception_name",""))&&System.currentTimeMillis()-p.getLong("reception_observed_at",0)<60000?p.getString("reception_"+field,""):"";}
 static String label(Context c,SatelliteState state,boolean ar){String s=value(c,state,"strength"),q=value(c,state,"quality"),n=value(c,state,"snr");return DirectReceiverSignal.sourceLabel(state,ar)+"  ·  "+(ar?"الإشارة ":"Signal ")+(s.isEmpty()?"—":s)+"   ·   "+(ar?"الجودة ":"Quality ")+(q.isEmpty()?"—":q)+"   ·   SNR "+(n.isEmpty()?"—":n);}
}
